(18926,3,0,'Once they\'re dealt with we can dedicate more resources to the war effort.',12,0,100,0,0,0,'Sleyin'),
(18952,0,0,'Death to the interlopers!',12,0,100,0,0,0,'Bonechewer Scavenger'),
