(24718,2,0,'Far out, man. This bucket of bolts might make it after all...',12,7,100,0,0,0,'Lebronski'),
(24719,0,0,'I\'m cryin\' here! Please, make the funny stop!',12,7,100,0,0,0,'Gwendolyn'),
